     3	import domain.Note;
     4	import sync.IncomingChange;
     5	
     6	/** Whole-note conflicts: the later edit wins, ties keep what the server has. */
     7	public final class ConflictResolver {
     8	    public enum Decision { CREATE, APPLY, KEEP_SERVER }
     9	
    10	    public Decision decide(Note stored, IncomingChange change) {
    11	        if (stored == null) {
    12	            return Decision.CREATE;
    13	        }
    14	        if (change.editedAt().isAfter(stored.updatedAt())) {
    15	            return Decision.APPLY;
    16	        }
    17	        return Decision.KEEP_SERVER;
    18	    }
    19	}
