     1	package service;
     2	
     3	import domain.Note;
     4	import store.FolderStore;
     5	import store.NoteStore;
     6	import sync.IncomingChange;
     7	import sync.PushResult;
     8	
     9	import java.util.ArrayList;
    10	import java.util.Comparator;
    11	import java.util.List;
    12	
    13	/**
    14	 * Devices work offline and upload their edits in batches when they get a connection.
    15	 * After a push the device pulls the change feed, so a change the server keeps
    16	 * ({@link ConflictResolver.Decision#KEEP_SERVER}) is still reported as synced: the device will receive the server copy.
    17	 */
    18	public class SyncService {
    19	    private final NoteStore notes;
    20	    private final FolderStore folders;
    21	    private final ConflictResolver resolver;
    22	    private final ChangeFeed feed;
    23	
    24	    public SyncService(NoteStore notes, FolderStore folders, ConflictResolver resolver, ChangeFeed feed) {
    25	        this.notes = notes;
    26	        this.folders = folders;
    27	        this.resolver = resolver;
    28	        this.feed = feed;
    29	    }
    30	
    31	    public PushResult push(String deviceId, List<IncomingChange> changes) {
    32	        List<IncomingChange> ordered = new ArrayList<>(changes);
    33	        // a device may queue several edits of the same note; apply them in the order they were made
    34	        ordered.sort(Comparator.comparing(IncomingChange::editedAt));
    35	        List<PushResult.Item> results = new ArrayList<>();
    36	        for (IncomingChange change : ordered) {
    37	            if (change.folderId() != null && folders.find(change.folderId()).isEmpty()) {
    38	                results.add(new PushResult.Item(change.noteId(), PushResult.Status.REJECTED, "unknown folder"));
    39	                continue;
    40	            }
    41	            Note stored = notes.find(change.noteId()).orElse(null);
    42	            switch (resolver.decide(stored, change)) {
    43	                case CREATE -> notes.save(Note.draft(change.noteId(), change.folderId(), change.title(), change.body(), change.editedAt()));
    44	                case APPLY -> notes.save(change.deleted()
    45	                        ? stored.asDeleted(change.editedAt())
    46	                        : stored.withContent(change.title(), change.body(), change.editedAt()));
    47	                case KEEP_SERVER -> {
    48	                }
    49	            }
    50	            results.add(new PushResult.Item(change.noteId(), PushResult.Status.SYNCED, null));
    51	        }
    52	        return new PushResult(List.copyOf(results), feed.currentRevision());
    53	    }
    54	}
