     1	package util;
     2	
     3	import java.time.DateTimeException;
     4	import java.time.Instant;
     5	import java.time.LocalDateTime;
     6	import java.time.OffsetDateTime;
     7	import java.time.ZoneId;
     8	import java.time.format.DateTimeFormatter;
     9	
    10	/** Device timestamps arrive as ISO-8601 text, with an offset ("...+09:00", "...Z") or as local time plus a zone. */
    11	public final class Timestamps {
    12	    private Timestamps() {
    13	    }
    14	
    15	    public static Instant parse(String text, ZoneId deviceZone) {
    16	        if (text == null || text.isBlank()) {
    17	            throw new IllegalArgumentException("timestamp required");
    18	        }
    19	        String s = text.trim();
    20	        try {
    21	            if (s.endsWith("Z") || s.matches(".*[+-]\\d{2}:\\d{2}$")) {
    22	                return OffsetDateTime.parse(s).toInstant();
    23	            }
    24	            return LocalDateTime.parse(s).atZone(deviceZone).toInstant();
    25	        } catch (DateTimeException e) {
    26	            throw new IllegalArgumentException("bad timestamp: " + text, e);
    27	        }
    28	    }
    29	
    30	    public static String format(Instant instant) {
    31	        return instant == null ? null : DateTimeFormatter.ISO_INSTANT.format(instant);
    32	    }
    33	}
