    10	/** Edits made in the web console (always online). */
    11	public class NoteService {
    12	    private static final int MAX_TITLE = 120;
    13	
    14	    private final NoteStore notes;
    15	    private final FolderStore folders;
    16	    private final Clock clock;
    17	    private final Ids ids = new Ids("note-");
    18	
    19	    public NoteService(NoteStore notes, FolderStore folders, Clock clock) {
    20	        this.notes = notes;
    21	        this.folders = folders;
    22	        this.clock = clock;
    23	    }
    24	
    25	    public Note create(String folderId, String title, String body) {
    26	        requireFolder(folderId);
    27	        return notes.save(Note.draft(ids.next(), folderId, cleanTitle(title), body == null ? "" : body, clock.instant()));
    28	    }
    29	
    30	    public Note edit(String id, String title, String body) {
    31	        Note note = get(id);
    32	        String newTitle = title == null ? note.title() : cleanTitle(title);
    33	        String newBody = body == null ? note.body() : body;
    34	        return notes.save(note.withContent(newTitle, newBody, clock.instant()));
    35	    }
    36	
    37	    public Note move(String id, String folderId) {
    38	        requireFolder(folderId);
    39	        return notes.save(get(id).movedTo(folderId, clock.instant()));
    40	    }
    41	
    42	    public Note get(String id) {
    43	        Note note = notes.find(id).orElseThrow(() -> new ApiException(404, "note not found"));
    44	        if (note.deleted()) {
    45	            throw new ApiException(404, "note not found");
    46	        }
    47	        return note;
    48	    }
    49	
    50	    private void requireFolder(String folderId) {
    51	        if (folderId == null || folders.find(folderId).isEmpty()) {
    52	            throw new ApiException(400, "unknown folder");
    53	        }
    54	    }
    55	
    56	    private static String cleanTitle(String title) {
    57	        String t = title == null ? "" : title.strip();
    58	        if (t.isEmpty() || t.length() > MAX_TITLE) {
    59	            throw new ApiException(400, "title must be 1-" + MAX_TITLE + " characters");
    60	        }
    61	        return t;
    62	    }
    63	}
=== src/api/SyncHandler.java
     1	package api;
     2	
     3	import domain.Note;
     4	import service.ApiException;
     5	import service.ChangeFeed;
     6	import service.SyncService;
     7	import sync.IncomingChange;
     8	import sync.PushResult;
     9	import util.FormCodec;
    10	import util.Timestamps;
    11	
    12	import java.time.DateTimeException;
    13	import java.time.ZoneId;
    14	import java.time.ZoneOffset;
    15	import java.util.ArrayList;
    16	import java.util.List;
    17	import java.util.Map;
    18	
    19	/**
    20	 * Mobile sync. Push body: one change per line, form-encoded
    21	 * ({@code id=..&folder=..&title=..&body=..&editedAt=..[&deleted=true]}).
    22	 * Headers: X-Device-Id, X-Device-Zone (used for timestamps sent without an offset).
    23	 */
    24	public class SyncHandler {
    25	    private final SyncService sync;
    26	    private final ChangeFeed feed;
    27	
    28	    public SyncHandler(SyncService sync, ChangeFeed feed) {
    29	        this.sync = sync;
    30	        this.feed = feed;
    31	    }
    32	
    33	    Response push(Request req) {
    34	        String device = req.header("X-Device-Id");
    35	        if (device == null || device.isBlank()) {
    36	            throw new ApiException(400, "X-Device-Id required");
    37	        }
    38	        ZoneId zone = zone(req.header("X-Device-Zone"));
    39	        List<IncomingChange> changes = new ArrayList<>();
    40	        for (String line : req.body().split("\n")) {
    41	            if (line.isBlank()) {
    42	                continue;
    43	            }
    44	            Map<String, String> f = FormCodec.decode(line);
    45	            if (f.get("id") == null) {
    46	                throw new ApiException(400, "change without id");
    47	            }
    48	            try {
    49	                changes.add(new IncomingChange(f.get("id"), f.get("folder"), f.getOrDefault("title", ""), f.getOrDefault("body", ""),
    50	                        Timestamps.parse(f.get("editedAt"), zone), Boolean.parseBoolean(f.get("deleted"))));
    51	            } catch (IllegalArgumentException e) {
    52	                throw new ApiException(400, e.getMessage());
    53	            }
    54	        }
    55	        PushResult result = sync.push(device, changes);
    56	        StringBuilder sb = new StringBuilder("{\"results\":[");
    57	        for (int i = 0; i < result.items().size(); i++) {
    58	            PushResult.Item item = result.items().get(i);
    59	            if (i > 0) {
    60	                sb.append(',');
    61	            }
    62	            sb.append("{\"id\":").append(Json.str(item.noteId()))
    63	                    .append(",\"status\":").append(Json.str(item.status().name().toLowerCase()))
    64	                    .append(",\"reason\":").append(Json.str(item.reason())).append('}');
    65	        }
    66	        return new Response(200, sb.append("],\"cursor\":").append(result.cursor()).append('}').toString());
    67	    }
    68	
    69	    Response changes(Request req) {
    70	        long since;
    71	        try {
    72	            since = Long.parseLong(req.param("since") == null ? "0" : req.param("since"));
    73	        } catch (NumberFormatException e) {
    74	            throw new ApiException(400, "bad cursor");
    75	        }
    76	        List<Note> changed = feed.since(since);
    77	        StringBuilder sb = new StringBuilder("{\"notes\":[");
    78	        for (int i = 0; i < changed.size(); i++) {
    79	            if (i > 0) {
    80	                sb.append(',');
    81	            }
    82	            sb.append(Json.note(changed.get(i)));
    83	        }
    84	        return new Response(200, sb.append("],\"cursor\":").append(feed.currentRevision()).append('}').toString());
    85	    }
    86	
    87	    private static ZoneId zone(String header) {
    88	        if (header == null || header.isBlank()) {
    89	            return ZoneOffset.UTC;
    90	        }
    91	        try {
    92	            return ZoneId.of(header.trim());
    93	        } catch (DateTimeException e) {
    94	            throw new ApiException(400, "bad X-Device-Zone");
    95	        }
    96	    }
    97	}

