    25	    private final SyncService sync;
    26	    private final ChangeFeed feed;
    27	
    28	    public SyncHandler(SyncService sync, ChangeFeed feed) {
    29	        this.sync = sync;
    30	        this.feed = feed;
    31	    }
    32	
    33	    Response push(Request req) {
    34	        String device = req.header("X-Device-Id");
    35	        if (device == null || device.isBlank()) {
    36	            throw new ApiException(400, "X-Device-Id required");
    37	        }
    38	        ZoneId zone = zone(req.header("X-Device-Zone"));
    39	        List<IncomingChange> changes = new ArrayList<>();
    40	        for (String line : req.body().split("\n")) {
    41	            if (line.isBlank()) {
    42	                continue;
    43	            }
    44	            Map<String, String> f = FormCodec.decode(line);
    45	            if (f.get("id") == null) {
    46	                throw new ApiException(400, "change without id");
    47	            }
    48	            try {
    49	                changes.add(new IncomingChange(f.get("id"), f.get("folder"), f.getOrDefault("title", ""), f.getOrDefault("body", ""),
    50	                        Timestamps.parse(f.get("editedAt"), zone), Boolean.parseBoolean(f.get("deleted"))));
    51	            } catch (IllegalArgumentException e) {
    52	                throw new ApiException(400, e.getMessage());
    53	            }
    54	        }
    55	        PushResult result = sync.push(device, changes);
    56	        StringBuilder sb = new StringBuilder("{\"results\":[");
    57	        for (int i = 0; i < result.items().size(); i++) {
    58	            PushResult.Item item = result.items().get(i);
    59	            if (i > 0) {
    60	                sb.append(',');
    61	            }
    62	            sb.append("{\"id\":").append(Json.str(item.noteId()))
    63	                    .append(",\"status\":").append(Json.str(item.status().name().toLowerCase()))
    64	                    .append(",\"reason\":").append(Json.str(item.reason())).append('}');
    65	        }
    66	        return new Response(200, sb.append("],\"cursor\":").append(result.cursor()).append('}').toString());
    67	    }
    68	
    69	    Response changes(Request req) {
    70	        long since;
    71	        try {
    72	            since = Long.parseLong(req.param("since") == null ? "0" : req.param("since"));
    73	        } catch (NumberFormatException e) {
    74	            throw new ApiException(400, "bad cursor");
    75	        }
    76	        List<Note> changed = feed.since(since);
    77	        StringBuilder sb = new StringBuilder("{\"notes\":[");
    78	        for (int i = 0; i < changed.size(); i++) {
    79	            if (i > 0) {
    80	                sb.append(',');
    81	            }
    82	            sb.append(Json.note(changed.get(i)));
    83	        }
    84	        return new Response(200, sb.append("],\"cursor\":").append(feed.currentRevision()).append('}').toString());
    85	    }
    86	
    87	    private static ZoneId zone(String header) {
    88	        if (header == null || header.isBlank()) {
    89	            return ZoneOffset.UTC;
    90	        }
    91	        try {
    92	            return ZoneId.of(header.trim());
    93	        } catch (DateTimeException e) {
    94	            throw new ApiException(400, "bad X-Device-Zone");
    95	        }
    96	    }
    97	}

