     1	package store;
     2	
     3	import domain.Audited;
     4	
     5	import java.time.Clock;
     6	import java.time.Instant;
     7	import java.util.ArrayList;
     8	import java.util.Comparator;
     9	import java.util.LinkedHashMap;
    10	import java.util.List;
    11	import java.util.Map;
    12	import java.util.Optional;
    13	import java.util.concurrent.atomic.AtomicLong;
    14	
    15	/**
    16	 * Base table for audited entities. Every save fills the audit columns
    17	 * (createdAt on first save, updatedAt, and the next revision) so callers cannot forget them.
    18	 */
    19	public class AuditingStore<T extends Audited<T>> {
    20	    private final Map<String, T> rows = new LinkedHashMap<>();
    21	    private final Clock clock;
    22	    private final AtomicLong revisions;
    23	
    24	    protected AuditingStore(Clock clock, AtomicLong revisions) {
    25	        this.clock = clock;
    26	        this.revisions = revisions;
    27	    }
    28	
    29	    public synchronized T save(T entity) {
    30	        Instant now = clock.instant();
    31	        T previous = rows.get(entity.id());
    32	        Instant created = previous != null ? previous.createdAt() : (entity.createdAt() != null ? entity.createdAt() : now);
    33	        T stamped = entity.withAudit(created, now, revisions.incrementAndGet());
    34	        rows.put(stamped.id(), stamped);
    35	        return stamped;
    36	    }
    37	
    38	    public synchronized Optional<T> find(String id) {
    39	        return Optional.ofNullable(rows.get(id));
    40	    }
    41	
    42	    public synchronized List<T> all() {
    43	        return new ArrayList<>(rows.values());
    44	    }
    45	
    46	    /** Rows saved after the given revision, oldest change first. */
